Alias.script:
local room = matches[2] or map.currentRoom
local x, y, z = getRoomCoordinates(room)
echo("Room Coordinates for " .. room .. ":")
echo("\n     X:" .. x)
echo("\n     Y:" .. y)
echo("\n     Z:" .. z)
echo("\nRoom Hash " .. getRoomHashByID(room))
echo("\nRoom Name " .. getRoomName(room))
for _, roomid in ipairs(getAllRoomEntrances(room)) do
  echo("\nRoom exits " .. _ .. ":" .. roomid)
end

Script.script:
GUI.BackgroundCSS = CSSMan.new([[
  background-color: rgb(20,0,20);
]])

GUI.Right = Geyser.Label:new({
  name = "GUI.Right",
  x = "-25%", y = 0,
  width = "25%",
  height = "100%",
})
GUI.Right:setStyleSheet(GUI.BackgroundCSS:getCSS())

GUI.Top = Geyser.Label:new({
  name = "GUI.Top",
  x = 0, y = 0,
  width = "75%",
  height = "5%",
})
GUI.Top:setStyleSheet(GUI.BackgroundCSS:getCSS())

GUI.Bottom = Geyser.Label:new({
  name = "GUI.Bottom",
  x = 0, y = "90%",
  width = "75%",
  height = "10%",
})
GUI.Bottom:setStyleSheet(GUI.BackgroundCSS:getCSS())

GUI.Footer = Geyser.HBox:new({
  name = "GUI.Footer",
  x = 0, y = 0,
  width = "100%",
  height = "100%",
}, GUI.Bottom)

GUI.LeftColumn = Geyser.VBox:new({
  name = "GUI.LeftColumn",
}, GUI.Footer)

GUI.MiddleColumn = Geyser.VBox:new({
  name = "GUI.MiddleColumn",
}, GUI.Footer)

GUI.RightColumn = Geyser.VBox:new({
  name = "GUI.RightColumn",
}, GUI.Footer)

GUI.GaugeBackCSS = CSSMan.new([[
  background-color: rgba(0,0,0,0);
  border-style: solid;
  border-color: white;
  border-width: 1px;
  border-radius: 5px;
  margin: 5px;
]])

GUI.GaugeFrontCSS = CSSMan.new([[
  background-color: rgba(0,0,0,0);
  border-style: solid;
  border-color: white;
  border-width: 1px;
  border-radius: 5px;
  margin: 5px;
]])

GUI.Health = Geyser.Gauge:new({
  name = "GUI.Health",
}, GUI.LeftColumn)
GUI.Health.back:setStyleSheet(GUI.GaugeBackCSS:getCSS())
GUI.GaugeFrontCSS:set("background-color","red")
GUI.Health.front:setStyleSheet(GUI.GaugeFrontCSS:getCSS())
GUI.Health:setValue(0, 100)
GUI.Health.front:echo("气血")

GUI.Mana = Geyser.Gauge:new({
