GUI.GaugeFrontCSS:set("background-color","DodgerBlue")
GUI.Endurance.front:setStyleSheet(GUI.GaugeFrontCSS:getCSS())
GUI.Endurance:setValue(0, 100)
GUI.Endurance.front:echo("内力")

GUI.Willpower = Geyser.Gauge:new({
