}, GUI.RightColumn)
GUI.Food.back:setStyleSheet(GUI.GaugeBackCSS:getCSS())
GUI.GaugeFrontCSS:set("background-color","tomato")
GUI.Food.front:setStyleSheet(GUI.GaugeFrontCSS:getCSS())
