GUI.Box1:echo("<center>GUI.Mapper</center>")

GUI.Box2 = Geyser.Label:new({
  name = "GUI.Box2",
  x = 0, y = "50%",
  width = "50%",
  height = "50%",
  message = [[<center>江湖笑 恩怨了</center>]]
